import React, { useEffect, useRef } from 'react';
import $ from 'jquery';
import 'jquery-ui-dist/jquery-ui';
import '@boldreports/javascript-reporting-controls/Scripts/v2.0/bold.report-viewer.min.js';
import '@boldreports/javascript-reporting-controls/Content/v2.0/tailwind-light/bold.report-viewer.min.css';

// Make jQuery global so Bold Reports can access it
(window as any).jQuery = $;
(window as any).$ = $;

interface BoldReportProps {
  apiUrl: string;       // API endpoint serving your RDL
  reportName: string;   // RDL file name
  tenantId?: string;    // Optional tenant
}

export const BoldReport: React.FC<BoldReportProps> = ({ apiUrl, reportName, tenantId }) => {
  const viewerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (viewerRef.current) {
      // Initialize the Bold Report Viewer
      // @ts-ignore
      $(viewerRef.current).BoldReportViewer({
        id: 'reportViewer',
        reportServiceUrl: apiUrl,
        reportPath: reportName,
        parameters: [
          { name: 'TenantId', value: tenantId || '00000000-0000-0000-0000-000000000000' },
          { name: 'ReportGeneratedOn', value: new Date().toISOString() },
        ],
        toolbarSettings: { showToolbar: true },
        height: '100%',
      });
    }
  }, [apiUrl, reportName, tenantId]);

  return <div ref={viewerRef} style={{ height: '900px', width: '100%' }} />;
};
